style.css:
body {  
    font-family: Arial, sans-serif;  
    background-color: #f9f0f5; /* Lichte roze achtergrond */  
    color: #6a0dad; /* Donkerdere paarse kleur voor tekst */  
}  

header {  
    background-color: #ff69b4; /* Fel roze */  
    padding: 20px;  
    text-align: center;  
}  

nav ul {  
    list-style-type: none;  
    padding: 0;  
}  

nav ul li {  
    display: inline;  
    margin: 0 15px;  
}  

nav ul li a {  
    color: white;  
    text-decoration: none;  
    font-weight: bold;  
}  

h1, h2 {  
    color: #6200ea; /* Donkerpaarse kleur voor koppen */  
}  

section {  
    margin: 20px;  
    padding: 10px;  
    border-radius: 5px;  
    background-color: #ffe4f1; /* Lichte roze voor secties */  
}  

footer {  
    text-align: center;  
    padding: 10px;  
    background-color: #ff69b4; /* Zelfde fel roze als header */  
    color: white;  
    position: relative;  
    bottom: 0;  
    width: 100%;  
}
